_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='equipment-exchange-co' AND approved AND profile IS NULL;
UPDATE companies SET description='Equipment Plus Total Facility Solutions was founded in 1987 by Robbie Taylor in Greenville, North Carolina. The company remains under the leadership of the Taylor family, with Laura Taylor also playing a key role. From its start as a foodservice equipment dealer, it has grown into a total facilities solutions provider for eastern North Carolina.

The firm supplies commercial kitchen equipment, offers equipment rentals, sells smallwares and chemicals, and provides parts, service, and preventive maintenance around the clock. Its 20,000‑square‑foot corporate center houses a showroom, a service dispatch center, a parts inventory valued at more than $250,000, and a custom fabrication shop. A staff of over 30 technicians and salespeople covers a 2,200‑square‑mile service area that includes Greenville, Washington, Wilson, Rocky Mount, New Bern, and surrounding communities.

Customers range from independent restaurants and catering operations to craft breweries and brewpubs. Named clients include Local Oak Brewery, G&K Cafe & Catering, Dickenson Avenue Public House, and Uptown Brewing Company. The company also promotes energy‑efficiency solutions for foodservice facilities.

Equipment Plus distinguishes itself with a “one‑stop‑shop” model that combines sales, installation, service, and project management under one roof, and it emphasizes a ministry‑first culture that directs community outreach and employee wellbeing.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Equipment sales", "Equipment rentals", "Small kitchenware sales", "Service and repair", "Chemical sales", "Parts sales", "Custom design", "Construction", "Financing", "Facility services", "Plumbing service", "Beverage and bar services", "Preventive maintenance", "Warranty service", "Project management", "Custom fabrication"], "industries": ["Foodservice", "Restaurant", "Brewery", "Catering", "Commercial kitchen", "Energy efficiency"], "materials": [], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["24/7 service department", "One-stop shop for equipment sales, service, rentals, design, chemicals, parts, and construction", "Over 30 employees covering a 2,200\u2011square\u2011mile service area", "$250,000+ on\u2011hand repair parts inventory", "20,000\u2011sq\u2011ft facility with showroom, dispatch, parts, and custom fabrication"], "facts_used": ["Founded in 1987 by Robbie Taylor -> /about-us", "Headquarters in Greenville, North Carolina -> /about-us", "20,000 sq ft corporate center with showroom, dispatch, parts inventory, custom fabrication -> /about-us", "Over 30 employees -> /about-us", "Service area 2,200 square miles -> /about-us", "$250,000+ on-hand repair parts inventory -> /about-us", "24/7 service department -> /", "One-stop shop model (sales, service, rentals, design, chemicals, parts, construction) -> /, /services", "Clients: Local Oak Brewery, G&K Cafe & Catering, Dickenson Avenue Public House, Uptown Brewing Company -> /", "Energy efficiency solutions mentioned -> /, industries_served", "Ministry-first culture and community outreach -> /, /about-us", "LinkedIn URL -> db"], "company_type": "Distributor / reseller", "make